function leftRightDifference(nums) {
  let rightSum = 0;
  for (const value of nums) {
    rightSum += value;
  }
  let leftSum = 0;
  const answer = [];
  for (let i = 0; i < nums.length; i++) {
    rightSum -= nums[i];
    answer.push(Math.abs(leftSum - rightSum));
    leftSum += nums[i];
  }
  return answer;
}

