function leftRightDifference(nums) {
  const result = [];
  for (let i = 0; i < nums.length; i++) {
    const before = nums.slice(0, i).reduce((acc, v) => acc + v, 0);
    const after = nums.slice(i + 1).reduce((acc, v) => acc + v, 0);
    result.push(before > after ? before - after : after - before);
  }
  return result;
}

